import{_ as a,b as o,c as e,I as s}from"./chunks/framework.C6cPs9Ia.js";const c=JSON.parse('{"title":"网页游戏黄金时代博物馆（个人馆藏）","description":"4399 考古学家的私人博物馆——洛克王国、赛尔号、摩尔庄园与那些 Flash 小游戏的黄金年代","frontmatter":{"title":"网页游戏黄金时代博物馆（个人馆藏）","date":"2026-09-16T00:00:00.000Z","tags":["网页游戏","怀旧",4399],"cover":"/LQY/images/cover-webgame.webp","head":[["meta",{"name":"description","content":"4399 考古学家的私人博物馆——洛克王国、赛尔号、摩尔庄园与那些 Flash 小游戏的黄金年代"}],["meta",{"name":"keywords","content":"4399, 网页游戏, 洛克王国, 赛尔号, 摩尔庄园, 怀旧, Flash"}]]},"headers":[],"relativePath":"posts/webgame-museum.md","filePath":"posts/webgame-museum.md"}'),r={name:"posts/webgame-museum.md"};function n(l,t,i,u,p,h){return o(),e("div",null,[...t[0]||(t[0]=[s('<p>欢迎来到本猫窝常设展厅：<strong>网页游戏黄金时代博物馆</strong>。馆长兼唯一的讲解员是我，营业时间随缘，闭馆原因通常是&quot;我妈喊我关电脑&quot;。</p><hr><h2 id="展厅一-宠物养成宇宙" tabindex="-1">展厅一：宠物养成宇宙 <a class="header-anchor" href="#展厅一-宠物养成宇宙" aria-label="Permalink to &quot;展厅一：宠物养成宇宙&quot;">​</a></h2><p><strong>洛克王国</strong>（2010 年开服）——我的第一个&quot;电子宠物债&quot;。格里芬院长的剧情、火花 的进化链、每周五更新的新宠图鉴……那时候一周最期待的不是周末，是周五下午放学冲回家看更新。</p><p><strong>赛尔号</strong>（2009 年）——雷伊登场那天，全班的课间讨论主题从动画片直接换成了&quot;你抽到雷伊没&quot;。盖亚和雷伊的对决海报，我贴在书桌前的墙上，贴了整整三年。</p><p><strong>摩尔庄园</strong>（2008 年）——严格来说我不是农民，我是去看拉姆的。那只小家伙哭的时候，我拿零花钱给它买礼物的手速，比现在抢任何东西都快。</p><div class="tip custom-block"><p class="custom-block-title">馆长锐评</p><p>这三个游戏教会了我最重要的一课：<strong>想要，就要等。</strong> 等作物成熟、等蛋孵化、等周五更新。现在动不动&quot;一键领取&quot;的游戏，反而没了那个味道。</p></div><h2 id="展厅二-flash-小游戏万神殿" tabindex="-1">展厅二：Flash 小游戏万神殿 <a class="header-anchor" href="#展厅二-flash-小游戏万神殿" aria-label="Permalink to &quot;展厅二：Flash 小游戏万神殿&quot;">​</a></h2><ul><li><strong>死神 VS 火影</strong>：双人模式，一人半边键盘，和表哥打到键盘差点分家。连招表手抄在数学本最后一页（导致我把&quot;卍解&quot;写进过作文）</li><li><strong>黄金矿工</strong>：人生第一课&quot;该出手时就出手，不该出手时抓石头也是白搭&quot;</li><li><strong>森林冰火人</strong>：和同桌合作，三分钟友尽，五分钟和好，循环十次</li><li><strong>狂扁小朋友</strong>：名字放今天绝对过不了审，但当年是真上头</li><li><strong>造梦西游</strong>：我玩的第一款有&quot;刷装备&quot;概念的游戏，悟空的棒子敲下去的那声，我现在还记得</li></ul><h2 id="展厅三-关于-flash-的消亡" tabindex="-1">展厅三：关于 Flash 的消亡 <a class="header-anchor" href="#展厅三-关于-flash-的消亡" aria-label="Permalink to &quot;展厅三：关于 Flash 的消亡&quot;">​</a></h2><p>Flash 停服那天，我在某个怀旧站上又玩了一局黄金矿工。</p><p>画面还是糊糊的，BGM 还是那一段，钩子甩下去还是那个抛物线。<strong>物理引擎没变，变的是屏幕前的人</strong>——当年那个写完作业能玩一下午的小孩，现在要靠月考排名来兑换游戏时间。</p><p>有人说网页游戏的时代结束了。我倒觉得没有——它们只是搬了个家，搬进像猫窝这样的小站里，搬进每个还记得&quot;4399 三个数字是彩色&quot;的人心里。</p><h2 id="馆藏预告" tabindex="-1">馆藏预告 <a class="header-anchor" href="#馆藏预告" aria-label="Permalink to &quot;馆藏预告&quot;">​</a></h2><p>最近在做一个&quot;网页游戏时代编年史&quot;的整理计划，按年份把记忆里的游戏、宠物、地图、梗全部编目。工程量巨大，可能会分成好几篇文（挖坑预警）。</p><p>如果你也有想考古的游戏，评论区报个名，馆长帮你排队安排展厅。喵~</p><p><em>——本馆免费开放，讲解员随时跑路去看新番，见谅。</em></p>',17)])])}const g=a(r,[["render",n]]);export{c as __pageData,g as default};
